/*
 Problem: 3090. Maximum Length Substring With Two Occurrences
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 9.1 MB (66.79%)
 Tags: Hash Table, String, Sliding Window
*/
class Solution {
public:
    int maximumLengthSubstring(string s) {
        int mx = 2;
        int ans = 0;
        int l = 0, r = 0;
        vector cnt(26, 0);

        while (r < s.size()) {
            ++cnt[s[r] - 'a'];

            while (cnt[s[r] - 'a'] > mx) {
                --cnt[s[l] - 'a'];
                ++l;
            }

            ans = max(ans, r - l + 1);
            ++r;
        }

        return ans;
    }
};
